+func TestTeleportProxyHello(t *testing.T) {
+	for _, tt := range []struct {
+		name       string
+		hello      string
+		clientAddr string
+	}{
+		{name: "client address", hello: "Teleport-Proxy{\"clientAddr\":\"192.0.2.10:1234\",\"tracingContext\":{\"trace\":\"value\"}}\x00SSH-2.0-test\r\n", clientAddr: "192.0.2.10:1234"},
+		{name: "no client address", hello: "Teleport-Proxy{}\x00SSH-2.0-test\r\n"},
+		{name: "standard SSH", hello: "SSH-2.0-test\r\n"},
+	} {
+		t.Run(tt.name, func(t *testing.T) {
+			listener, err := net.Listen("tcp", "127.0.0.1:0")
+			require.NoError(t, err)
+			mux, err := New(Config{Listener: listener})
+			require.NoError(t, err)
+			sshListener := mux.SSH()
+			go mux.Serve()
+			defer func() {
+				mux.Close()
+				mux.Wait()
+			}()
+
+			client, err := net.Dial("tcp", listener.Addr().String())
+			require.NoError(t, err)
+			defer client.Close()
+			_, err = io.WriteString(client, tt.hello)
+			require.NoError(t, err)
+
+			server, err := sshListener.Accept()
+			require.NoError(t, err)
+			defer server.Close()
+			require.Equal(t, ProtoSSH, server.(*Conn).Protocol())
+			wantAddr := client.LocalAddr().String()
+			if tt.clientAddr != "" {
+				wantAddr = tt.clientAddr
+				require.IsType(t, &net.TCPAddr{}, server.RemoteAddr())
+			}
+			require.Equal(t, wantAddr, server.RemoteAddr().String())
+			got := make([]byte, len(tt.hello))
+			_, err = io.ReadFull(server, got)
+			require.NoError(t, err)
+			require.True(t, bytes.Equal([]byte(tt.hello), got))
+		})
+	}
+}
